@startuml chat-stop-proxy-architecture
skinparam classAttributeIconSize 0
skinparam classFontSize 12
skinparam packageStyle rectangle
skinparam class {
  BackgroundColor #FAFAFA
  BorderColor #888888
  ArrowColor #555555
}

package "React Components (HQ Panel)" {
  class "HQ/index.tsx" as HQIndex {
    Composes ChatInput + MessageList
    Wires props from useHQ hooks
  }

  class "ChatInput.tsx" <<component>> {
    + value: string
    + onChange: (v: string) => void
    + onSend: (text: string) => void
    + disabled?: boolean
    + isLoading?: boolean
    + onStop?: () => void
    + chatMode?: 'llm' | 'claude'
    + onModeChange?: (mode) => void
    --
    Renders <Square> when isLoading
    Renders mode toggle in footer
    Blocks Enter key when isLoading
  }

  class "MessageList.tsx" <<component>> {
    + messages: Message[]
    --
    Renders CC badge when
    source === 'claude-code'
  }
}

package "React Hooks" {
  class "useHQ.tsx" <<hook>> {
    + handleSend(prompt: string): void
    + handleStop(): void
    --
    Branches on chatMode in handleSend:
    'llm' path → askLlm()
    'claude' path → writeToTerminal()
  }
}

package "State (Zustand)" {
  class "chatStore.ts" <<store>> {
    + isLoading: boolean
    + chatMode: 'llm' | 'claude'
    + outputByTarget: Record<string, OutputState>
    --
    + setLoading(v: boolean): void
    + setChatMode(mode): void
    + addMessage(msg): void
    + updateLastMessage(patch): void
    + appendOutputLine(target, line): void
    + setCommandRunning(target, v): void
  }
}

package "Lib" {
  class "llmBridge.ts" <<lib>> {
    + abortLlm(): void
    --
    Calls window.pathly.llm.abort()
  }

  class "launchTerminal.ts" <<lib>> {
    + writeToTerminal(
        adapter, prompt,
        projectPath, tabs,
        addTab, open, toggle
      ): Promise<string>
    --
    Returns tabId
  }
}

HQIndex --> "ChatInput.tsx" : renders
HQIndex --> "MessageList.tsx" : renders
HQIndex ..> "useHQ.tsx" : consumes hooks

"useHQ.tsx" --> "chatStore.ts" : reads / writes state
"useHQ.tsx" --> "llmBridge.ts" : handleStop calls abortLlm()
"useHQ.tsx" --> "launchTerminal.ts" : claude path calls writeToTerminal()

"ChatInput.tsx" ..> "useHQ.tsx" : onSend / onStop / onModeChange
"MessageList.tsx" --> "chatStore.ts" : reads messages

@enduml
